import time

def tri_insertion(t):
    for i in range(1, len(t)):
        cle = t[i]; j = i-1
        while j >= 0 and t[j] > cle:
            t[j+1] = t[j]; j -= 1
        t[j+1] = cle

for n in [100, 200, 400]:
    t = list(range(n, 0, -1))  # pire cas : décroissant
    start = time.time()
    tri_insertion(t)
    print(f'n={n}: {(time.time()-start)*1000:.2f}ms')

